package zw.co.hyperfeeds.notifications;
import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/notifications")public class NotificationController{private final JdbcClient jdbc;public NotificationController(JdbcClient j){jdbc=j;}@GetMapping List<Map<String,Object>>list(Authentication a,@RequestParam(defaultValue="false")boolean unreadOnly){return jdbc.sql("select id,type,title,body,data,read_at,created_at from notifications where user_id=:u and (:unread=false or read_at is null) order by created_at desc limit 100").param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).param("unread",unreadOnly).query().listOfRows();}@PutMapping("/{id}/read")@ResponseStatus(HttpStatus.NO_CONTENT)void read(Authentication a,@PathVariable UUID id){jdbc.sql("update notifications set read_at=coalesce(read_at,now()) where id=:id and user_id=:u").param("id",id).param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).update();}}
